window.roroSubmitButton=function(buttonId=null,formId=null){if(!formId||!buttonId)return;const form=document.getElementById(formId),button=document.getElementById(buttonId);if(!form||!button||button.type!=="submit")return;roroShowOverlay(!0);const processAjax=()=>{if(!form.reportValidity()){roroShowOverlay(!1);return}const formData=new FormData(form);fetch(form.getAttribute("action")||"",{method:(form.getAttribute("method")||"POST").toUpperCase(),body:formData,headers:{"X-Requested-With":"XMLHttpRequest",Accept:"application/json"}}).then(async response=>{const data=await response.clone().json().catch(()=>null);response.ok?RoroDom.emit(form,"roro:ajax:success",data):(RoroDom.emit(form,"roro:ajax:error",{status:response.status,response,responseJSON:data}),button.dataset.ajaxErrors&&data&&data.errors&&populateFormErrors(form,data.errors))}).catch(error=>{RoroDom.emit(form,"roro:ajax:error",{status:0,error})}).finally(()=>roroShowOverlay(!1))},processClassic=()=>{form.reportValidity()?form.submit():roroShowOverlay(!1)};button.dataset.ajax?processAjax():processClassic()},window.roroRegisterButtonOnClick=function(buttonId){const button=document.getElementById(buttonId);button&&RoroDom.on(button,"click",function(event){event.preventDefault(),roroSubmitButton(button.id,button.dataset.formId)})},window.roroShowOverlay=function(show=!0){const overlay=document.getElementById("roro-form-overlay");overlay&&(overlay.style.display=show?"flex":"none")},window.populateFormErrors=function(form,errors){clearFormErrors(form);for(let[inputName,messages]of Object.entries(errors)){inputName=normalizeInputName(inputName);const input=form.querySelector(`[name="${inputName}"]`);input&&roroShowError(input.id,messages.join(", "),!0)}},window.clearFormErrors=function(form){RoroDom.qsa(form,".roro-input").forEach(function(el){roroShowError(el.id,"",!1)})},RoroDom.ready(function(){RoroDom.qsa(".roro-btn-submit").forEach(function(btn){roroRegisterButtonOnClick(btn.id)}),RoroDom.qsa(".roro-border-error").forEach(function(el){manageBorderError(el)})});
